.tabset-tabs {
    --now-tabs--color--selected: 255, 255, 255;
    --now-tabs--color: 222, 222, 222;
    --now-tabs--color--active: 255, 255, 255;
    --now-tabs--color--hover: 255, 255, 255;
    --now-tabs--border-color--selected: 255, 255, 255;
