    --now-tabs_divider--width: 0.1px;
    --now-color_focus-ring: transparent;
    --now-tabs--border-width: 1px;
    --now-tabs--font-family: var(--Typography-Font---now-font-family, Lato);
    font-style: normal;
    font-weight: 400;
    line-height: normal;
    --now-tabs--scale-size-block: 2;
}

